        .slowena(slowena),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Expected counter model variable
    reg [3:0] expected_q;

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        slowena = 0;
        expected_q = 4'd0;

        // Apply synchronous reset test
        @(posedge clk);
        reset = 1;
        slowena = 1;
        @(posedge clk);
        #1; // Wait for output update
        if (q !== 4'd0) begin
            $display("Error: Reset failed. Expected 0, got %d", q);
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        reset = 0;
        expected_q = 4'd0;
        #1;
        if (q !== expected_q) begin
            $display("Error: Post-reset mismatch. Expected %d, got %d", expected_q, q);
            errors = errors + 1;
        end

        // Test 1: Pause functionality (slowena = 0)
        // Counter should hold value when slowena is low
        slowena = 0;
        repeat (3) begin
            @(posedge clk);
            #1;
            if (q !== expected_q) begin
                $display("Error: Pause failed. Expected %d, got %d", expected_q, q);
                errors = errors + 1;
            end
        end

        // Test 2: Decade counting from 0 to 9 and wrap around with slowena = 1
        slowena = 1;
        for (i = 0; i < 25; i = i + 1) begin
            @(posedge clk);
            #1;
            // Compute expected next state for decade counter (0-9)
            if (expected_q == 4'd9) begin
                expected_q = 4'd0;
            end else begin
                expected_q = expected_q + 1;
            end

            if (q !== expected_q) begin
                $display("Error at step %0d: Expected %d, got %d", i, expected_q, q);
                errors = errors + 1;
            end
        end

        // Test 3: Asynchronous-like/Synchronous Reset during active counting
        @(posedge clk);
        reset = 1;
        slowena = 1;
        expected_q = 4'd0;
        @(posedge clk);
        #1;
        if (q !== 4'd0) begin
            $display("Error: Mid-count reset failed. Expected 0, got %d", q);
            errors = errors + 1;
        end

        // Release reset and verify resumption
        reset = 0;
        @(posedge clk);
        #1;
        expected_q = 4'd1;
        if (q !== expected_q) begin
            $display("Error: Resumption after reset failed. Expected %d, got %d", expected_q, q);
            errors = errors + 1;
        end

        // Final evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
